const out = $input.first().json.stdout || '';
const paths = out.split('\n').filter(p => p.length > 0);
return paths.map(path => {
  const cls =
    path.startsWith('/Users/m2ultra/NOIZYANTHROPIC/.claude/rules/') ? 'DOCTRINE' :
    path.startsWith('/Users/m2ultra/NOIZYANTHROPIC/.claude/agents/') ? 'AGENT_DEF' :
    path.startsWith('/Users/m2ultra/NOIZYANTHROPIC/.claude/skills/') ? 'SKILL' :
    path.startsWith('/Users/m2ultra/NOIZYANTHROPIC/registry/') ? 'REGISTRY' :
    path.includes('MANIFESTO') ? 'MANIFESTO' :
    path.startsWith('/Users/m2ultra/NOIZYANTHROPIC/docs/governance/') ? 'GOVERNANCE' :
    path.match(/\\/(apps|mc96|cloudflare\/workers)\\/.*\\/src\\//) ? 'CODE_RUNTIME' :
    path.match(/\\/(tools|scripts|ops)\\//) ? 'CODE_TOOL' :
    path.endsWith('.sql') ? 'SCHEMA' :
    path.match(/(wrangler\\.|package\\.json|\\.env)/) ? 'CONFIG' :
    path.includes('PlowmansChronicles') ? 'CHRONICLE' :
    path.match(/\\/master-deck\\//) ? 'DECK_SOURCE' :
    path.includes('/public/web/designs/') ? 'DESIGN' :
    path.includes('/scan-reports/') || path.includes('/audits/') ? 'AUDIT' :
    path.includes('dazeflow-') ? 'DAZEFLOW' :
    'UNCLASSIFIED';
  return {
    json: {
      path,
      class: cls,
      ts: new Date().toISOString()
    }
  };
});
